import{_ as i,l as s,o as e,c as l,v as t,p as n,x as o,d as E,i as h,S as M}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"MEMS 图形化","description":"","frontmatter":{"title":"MEMS 图形化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mems-patterning.md","filePath":"litho/mems-patterning.md","lastUpdated":1789023840000}'),d={name:"litho/mems-patterning.md"};function p(m,a,c,S,_,B){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="mems-图形化" tabindex="-1">MEMS 图形化 <a class="header-anchor" href="#mems-图形化" aria-label="Permalink to &quot;MEMS 图形化&quot;">​</a></h1><div class="epigraph"><p>MEMS 要的是深槽、厚胶和释放后的三维；分辨率往往不是墙，深宽比、残余应力和双面套刻才是。</p><footer>—— 对照 MEMS 光刻与 Bosch 深硅刻蚀的通称</footer></div><p><a href="/litho/photonics-patterning">上一课</a>把目标函数换成损耗。缺口是力学器件。本课钉 MEMS 图形化。灰度把第三维写进胶厚，留给[下一课](/litho/grayscale-litho）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>惯性传感器、喷墨、射频 MEMS：胶厚可达数十微米，曝光用接触/接近式或专用投影，DOF 与侧壁垂直度关键。深硅常用 Bosch 时分钝化（各向异性课对照过）。双面光刻对准、释放孔、残余应力导致的翘曲，比 MMP 更像封装面板问题。LIGA 的 X 射线厚胶是尼奇。</p><p>缺口是<strong>厚胶三维</strong>，不是先进节点 k1。用 EUV 随机语言谈 MEMS 会错对象。</p><h3 id="与-cmos-mems-集成" tabindex="-1">与 CMOS-MEMS 集成 <a class="header-anchor" href="#与-cmos-mems-集成" aria-label="Permalink to &quot;与 CMOS-MEMS 集成&quot;">​</a></h3><p>共集成时前道光刻污染 MEMS 释放，或 MEMS 形貌破坏后道光刻焦深。集成顺序是 DTCO。</p><p><span class="marginnote">接触式光刻的颗粒打印在厚胶 MEMS 上仍致命，只是杀手尺寸不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工具：接触对准机、厚胶步进器。工艺：多层套刻、释放、超临界干燥（塌缩课同族）。计量：剖面、应力、动静态电学。灰度下一课可服务斜面与透镜。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>厚胶吸收与显影前沿给出倾斜侧壁，除非工艺针对垂直。Bosch 扇形波纹进力学疲劳。应力与光刻图形密度通过结构刚度耦合——布局即力学。</p>',13)),(e(),n(M,null,{default:o(()=>[h(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20THK%5B%22%E5%8E%9A%E8%83%B6%22%5D%20--%3E%20MEMS%5B%22%E6%B7%B1%E6%A7%BD%20%2F%20%E7%BB%93%E6%9E%84%22%5D%0A%20%20BOSCH%5B%22%E6%97%B6%E5%88%86%E9%92%9D%E5%8C%96%E5%88%BB%E8%9A%80%22%5D%20--%3E%20MEMS%0A%20%20STRESS%5B%22%E6%AE%8B%E4%BD%99%E5%BA%94%E5%8A%9B%22%5D%20--%3E%20MECH%5B%22%E7%BF%98%E6%9B%B2%20%2F%20%E9%A2%91%E5%81%8F%22%5D%0A%20%20MEMS%20--%3E%20MECH%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把所有 MEMS 当 Bosch。不进入某传感器设计。X 射线 LIGA 仅尼奇。</p><p>后课默认：MEMS 常要三维胶轮廓；下一课灰度曝光故意把剂量写成高度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MEMS 光刻墙在厚胶、深宽比、应力与双面套刻。</li><li>Bosch 与释放工艺定义侧壁，分辨率其次。</li><li>与 CMOS 共集成是顺序 DTCO。</li><li>出处：MEMS 光刻与深硅刻蚀通称。</li></ul>',5))])}const A=i(d,[["render",p]]);export{f as __pageData,A as default};
